    expect(second.meshCount).toBe(first.meshCount);
    expect(second.padCount).toBe(first.padCount);
    expect(second.viaCount).toBe(first.viaCount);
    expect(second.traceSegmentCount).toBe(first.traceSegmentCount);
  });
});

